-- Verify
select member_type, member_status, count(*) from ocp_register
  group by member_type, member_status order by 3 desc limit 10;
select count(*) as total,
       count(*) filter (where member_status='Active') as active,
       count(*) filter (where injection_training) as injection_certified
  from ocp_register;
